// Obtener valores desde otros nodos
const correctAction = $node["PredecirAcción"].json.recommended_action;
const operatorAction = $node["Webhook"].json.body.operator_action;
const feedbackText = $node["Corregir"].json.output;

// Comparación estricta
const isCorrect = correctAction === operatorAction;

// Score automático
const score = isCorrect ? 1 : 0;

return [
  {
    json: {
      correct_action: correctAction,
      is_correct: isCorrect,
      score: score,
      feedback_text: feedbackText,
      feedback_json: {
        reason_tag: isCorrect ? "correct" : "incorrect"
      }
    }
  }
];
